package com.shopsphere.controller;
import com.shopsphere.model.User; import com.shopsphere.service.AuthService; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.IOException;
@WebServlet({"/login","/register","/logout"}) public class AuthServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String path=q.getServletPath();if(path.equals("/logout")){HttpSession s=q.getSession(false);if(s!=null)s.invalidate();p.sendRedirect(q.getContextPath()+"/products?message=You+have+logged+out");return;}q.getRequestDispatcher(path.equals("/login")?"/WEB-INF/views/login.jsp":"/WEB-INF/views/register.jsp").forward(q,p);}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String path=q.getServletPath();try{if(path.equals("/register")){new AuthService().register(q.getParameter("name"),q.getParameter("email"),q.getParameter("password"),q.getParameter("mobile"));p.sendRedirect(q.getContextPath()+"/login?registered=1");return;}User u=new AuthService().login(q.getParameter("email"),q.getParameter("password"));if(u==null){q.setAttribute("error","Email or password is incorrect.");q.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(q,p);return;}HttpSession old=q.getSession(false);if(old!=null)old.invalidate();HttpSession s=q.getSession(true);s.setAttribute("user",u);s.setMaxInactiveInterval(30*60);p.sendRedirect(q.getContextPath()+("ADMIN".equals(u.getRole())?"/admin":"/products"));}catch(IllegalArgumentException e){q.setAttribute("error",e.getMessage());q.getRequestDispatcher(path.equals("/register")?"/WEB-INF/views/register.jsp":"/WEB-INF/views/login.jsp").forward(q,p);}catch(Exception e){throw new ServletException("Authentication operation failed",e);}}
}
